import{_ as p,a0 as u,w as l,s as o,ao as i,I as s,x as t,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在Ubuntu中安装XScreenSaver | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu中安装XScreenSaver | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu中安装XScreenSaver | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu中安装XScreenSaver | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Installing XScreenSaver In Ubuntu","title":"在Ubuntu中安装XScreenSaver","tag":"201310","desc":""},"relativePath":"201310/Installing XScreenSaver In Ubuntu.md","filePath":"[post].md"}'),d={name:"201310/Installing XScreenSaver In Ubuntu.md"};function m(S,e,g,v,x,T){const n=u("Link");return l(),o("div",null,[e[14]||(e[14]=i('<h1 id="在ubuntu中安装xscreensaver" tabindex="-1">在Ubuntu中安装XScreenSaver <a class="header-anchor" href="#在ubuntu中安装xscreensaver" aria-label="Permalink to “在Ubuntu中安装XScreenSaver”">​</a></h1><p>这个教程将会给你展示如何在Ubuntu 12.04(也包含其他Ubuntu版本)中加入屏幕保护，它们原本不包含X-windows屏幕保护程序。不过，一些对计算机或linux不熟悉的人，并不了解屏幕保护。到底屏幕保护能做什么呢?</p><p>屏幕保护是一个主要用于安全用途的计算机程序（译注：和最初屏幕保护的用途不同了）。当计算机空闲时，这个程序会清空屏幕或者在屏幕上填满移动的图片或图样。屏幕保护也可以用于娱乐或显示系统信息。当你打算离开办公室又不想让任何人看你电脑上的信息时，屏保程序将是绝佳的解决方案。</p><p>###屏幕保护怎么让我的电脑变得更安全？</p><p>屏幕保护能配置成在允许用户继续工作之前要求用户输入密码。但是请留意，如果设置为在启动机器后自动登入帐号，那么攻击者可以轻易的重启机器来登入你的帐号。</p><p>###怎么安装屏幕保护？</p><p>打开一个新的终端(ctrl+alt+T)，如图一所示。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen1.png" alt=""> 图一</p><p>在安装一个新的屏幕保护之前我们必须卸载默认屏幕保护，运行 &#39;sudo apt-get remove gnome-screensaver&#39; ，见图二。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen4.png" alt=""> 图二</p><p>用下列命令安装XScreenSaver和一些附加的屏保包。 sudo apt-get install xscreensaver xscreensaver-data-extra xscreensaver-gl-extra</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen6.png" alt=""> 图三</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen7.png" alt=""> 图四</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/screen9.png" alt=""> 图五</p>',14)),s("p",null,[e[1]||(e[1]=t("XScreenSaver 每次启动后会随机选择一个屏幕保护.预了解如何配置XScreenSaver，参见",-1)),r(n,{href:"http://www.jwz.org/xscreensaver/faq.html"},{default:a(()=>[...e[0]||(e[0]=[t("这里",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[15]||(e[15]=s("hr",null,null,-1)),s("p",null,[e[4]||(e[4]=t("via: ",-1)),r(n,{href:"http://www.unixmen.com/installing-xscreensaver-ubuntu/"},{default:a(()=>[...e[3]||(e[3]=[t("http://www.unixmen.com/installing-xscreensaver-ubuntu/",-1)])]),_:1})]),s("p",null,[e[7]||(e[7]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[5]||(e[5]=[t("LCTT",-1)])]),_:1}),e[8]||(e[8]=t(" 原创翻译，",-1)),r(n,{href:"http://linux.cn/"},{default:a(()=>[...e[6]||(e[6]=[t("Linux中国",-1)])]),_:1}),e[9]||(e[9]=t(" 荣誉推出",-1))]),s("p",null,[e[12]||(e[12]=t("译者：",-1)),r(n,{href:"https://github.com/Luoxcat"},{default:a(()=>[...e[10]||(e[10]=[t("Luoxcat",-1)])]),_:1}),e[13]||(e[13]=t(" 校对：",-1)),r(n,{href:"https://github.com/jasminepeng"},{default:a(()=>[...e[11]||(e[11]=[t("jasminepeng",-1)])]),_:1})])])}const X=p(d,[["render",m]]);export{w as __pageData,X as default};
